// Fresh hardware WebGL2 context for the bounded adoption evaluation.
import { chromium } from '@playwright/test';
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';

export async function openGPU() {
  const browser = await chromium.launch({
    executablePath: existsSync(chromium.executablePath())
      ? chromium.executablePath()
      : '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: true,
    args: ['--use-angle=metal'],
  });
  const page = await browser.newPage();
  await page.setContent('<canvas width="1280" height="720"></canvas>');
  const helper = await readFile(new URL('../../../webgl.mjs', import.meta.url), 'utf8');
  await page.addScriptTag({ content: helper.replaceAll('export ', '') });
  const hardware = await page.evaluate(() => {
    const gl = document.querySelector('canvas').getContext('webgl2', { antialias: false });
    if (!gl || !gl.getExtension('EXT_color_buffer_float')) throw Error('Float WebGL2 required');
    const debug = gl.getExtension('WEBGL_debug_renderer_info');
    const timer = gl.getExtension('EXT_disjoint_timer_query_webgl2');
    gl.bindVertexArray(gl.createVertexArray());
    // Match the native suite's complete neutral environment texture.
    const env = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, env);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      1,
      1,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      new Uint8Array([128, 128, 128, 255]),
    );
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    window.probe = { gl, timer, env, programs: new Map(), targets: new Map() };
    window.target = (width, height, float, count) => {
      const key = [width, height, float, count].join('/');
      let target = window.probe.targets.get(key);
      if (!target) {
        const fb = gl.createFramebuffer(),
          attachments = [];
        gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
        for (let i = 0; i < count; i++) {
          const texture = gl.createTexture();
          gl.bindTexture(gl.TEXTURE_2D, texture);
          gl.texStorage2D(gl.TEXTURE_2D, 1, float ? gl.RGBA32F : gl.RGBA8, width, height);
          gl.framebufferTexture2D(
            gl.FRAMEBUFFER,
            gl.COLOR_ATTACHMENT0 + i,
            gl.TEXTURE_2D,
            texture,
            0,
          );
          attachments.push(gl.COLOR_ATTACHMENT0 + i);
        }
        target = { fb, attachments };
        window.probe.targets.set(key, target);
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, target.fb);
      gl.drawBuffers(target.attachments);
      gl.readBuffer(gl.COLOR_ATTACHMENT0);
      gl.bindTexture(gl.TEXTURE_2D, env);
      gl.viewport(0, 0, width, height);
      if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE)
        throw Error('Incomplete framebuffer');
    };
    return {
      renderer: gl.getParameter(debug ? debug.UNMASKED_RENDERER_WEBGL : gl.RENDERER),
      vendor: gl.getParameter(debug ? debug.UNMASKED_VENDOR_WEBGL : gl.VENDOR),
      version: gl.getParameter(gl.VERSION),
      userAgent: navigator.userAgent,
      timerQueryAvailable: !!timer,
    };
  });
  if (/SwiftShader|llvmpipe/i.test(hardware.renderer)) {
    await browser.close();
    throw Error('Hardware GPU required: ' + hardware.renderer);
  }
  const command = async (request) => {
    if (request.op === 'quit') return {};
    return page.evaluate(async (request) => {
      const { gl, timer, programs } = window.probe;
      if (request.op === 'compile') {
        let source = request.fragment;
        if (!/layout\s*\(\s*location\s*=\s*0\s*\)\s*out vec4 outColor/.test(source))
          source = source.replace('out vec4 outColor;', 'layout(location=0) out vec4 outColor;');
        const shader = compileProgram(gl, request.vertex, source);
        shader.outputs = /layout\s*\(\s*location\s*=\s*3\s*\)/.test(source) ? 4 : 1;
        programs.set(request.name, shader);
        return { glError: gl.getError() };
      }
      const shader = programs.get(request.name);
      if (!shader) throw Error('Unknown program ' + request.name);
      gl.useProgram(shader.program);
      shader.set(request.uniforms);
      if (request.op === 'draw') {
        window.target(1, 1, true, shader.outputs);
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        const pixels = [];
        for (let i = 0; i < shader.outputs; i++) {
          gl.readBuffer(gl.COLOR_ATTACHMENT0 + i);
          const buffer = new Float32Array(4);
          gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.FLOAT, buffer);
          pixels.push(...buffer);
        }
        while (pixels.length < 16) pixels.push(0);
        return {
          glError: gl.getError(),
          pixels: pixels.map((x) => (Number.isFinite(x) ? x : null)),
        };
      }
      if (request.op !== 'render') throw Error('Unsupported operation ' + request.op);
      const { width, height, frames = 10, warmup = 5 } = request;
      window.target(width, height, false, 1);
      const finish = () => gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
      for (let i = 0; i < warmup; i++) gl.drawArrays(gl.TRIANGLES, 0, 3);
      finish();
      // A single elapsed-time query covers the whole completed block. On this
      // ANGLE Metal stack, separate queries around queued draws report times
      // whose sum greatly exceeds completed-block wall time (retained separately).
      const query = timer ? gl.createQuery() : null,
        begin = performance.now();
      if (query) gl.beginQuery(timer.TIME_ELAPSED_EXT, query);
      for (let i = 0; i < frames; i++) {
        gl.drawArrays(gl.TRIANGLES, 0, 3);
      }
      if (query) gl.endQuery(timer.TIME_ELAPSED_EXT);
      finish();
      const blockMilliseconds = performance.now() - begin;
      const milliseconds = [];
      if (query) {
        const deadline = performance.now() + 30000;
        while (!gl.getQueryParameter(query, gl.QUERY_RESULT_AVAILABLE)) {
          if (performance.now() > deadline) throw Error('GPU timer timeout');
          await new Promise((resolve) => setTimeout(resolve, 1));
        }
        milliseconds.push(gl.getQueryParameter(query, gl.QUERY_RESULT) / 1e6 / frames);
        gl.deleteQuery(query);
      }
      const disjoint = timer ? gl.getParameter(timer.GPU_DISJOINT_EXT) : false;
      let pixels;
      if (request.capture) {
        const buffer = new Uint8Array(width * height * 4);
        gl.readPixels(0, 0, width, height, gl.RGBA, gl.UNSIGNED_BYTE, buffer);
        pixels = Array.from(buffer);
      }
      return { glError: gl.getError(), disjoint, milliseconds, blockMilliseconds, pixels };
    }, request);
  };
  return {
    hardware,
    command,
    compile: (name, vertex, fragment) => command({ op: 'compile', name, vertex, fragment }),
    close: () => browser.close(),
  };
}

import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { openGPU } from './browser-gpu.mjs';
import { rendererVariant, variantFiles } from '../renderer.mjs';
import { vertex, fragment } from '../../../../web/shader.js';
const dir = 'research/diagnostics/algorithm1010/';
const native = JSON.parse(await readFile(dir + 'results/benchmark.json', 'utf8'));
const scenes = native.measurements.filter(
  (x) => x.width === 1280 && x.variant === 'production' && x.round === 0,
);
const names = ['production', 'odm-direct'];
const gpu = await openGPU(),
  measurements = [],
  shaderHashes = {};
const median = (xs) => {
  const a = xs.slice().sort((a, b) => a - b),
    n = a.length;
  return (a[Math.floor((n - 1) / 2)] + a[Math.floor(n / 2)]) / 2;
};
try {
  console.log(JSON.stringify(gpu.hardware));
  for (const name of names) {
    const source = await rendererVariant(fragment, name);
    shaderHashes[name] = createHash('sha256').update(source).digest('hex');
    if (shaderHashes[name] !== native.shaderHashes[name]) throw Error('Native shader changed');
    await gpu.compile(name, vertex, source);
  }
  for (const [index, scene] of scenes.entries())
    for (let round = 0; round < 3; round++) {
      const order = (round + index) % 2 ? names.slice().reverse() : names;
      for (const name of order) {
        const r = await gpu.command({
          op: 'render',
          name,
          uniforms: scene.uniforms,
          width: 1280,
          height: 720,
          frames: 30,
          warmup: 5,
        });
        if (r.glError || r.disjoint) throw Error('Invalid timing block: ' + JSON.stringify(r));
        const sample = {
          variant: name,
          scene: scene.scene,
          round,
          width: 1280,
          height: 720,
          frames: 30,
          warmup: 5,
          gpuMilliseconds: r.milliseconds,
          blockMilliseconds: r.blockMilliseconds,
          completionMillisecondsPerFrame: r.blockMilliseconds / 30,
          uniforms: scene.uniforms,
        };
        measurements.push(sample);
        console.log(
          scene.scene,
          name,
          round,
          'GPU median',
          r.milliseconds.length ? median(r.milliseconds).toFixed(3) : 'unavailable',
          'completion/frame',
          (r.blockMilliseconds / 30).toFixed(3),
        );
      }
    }
  const summaries = scenes.flatMap((scene) =>
    names.map((variant) => {
      const blocks = measurements.filter((x) => x.scene === scene.scene && x.variant === variant);
      const times = blocks.flatMap((x) => x.gpuMilliseconds);
      return {
        scene: scene.scene,
        variant,
        gpuMedianMilliseconds: times.length ? median(times) : null,
        completionMedianMilliseconds: median(blocks.map((x) => x.completionMillisecondsPerFrame)),
        gpuBlockMedians: blocks.map((x) =>
          x.gpuMilliseconds.length ? median(x.gpuMilliseconds) : null,
        ),
        completionBlockMeans: blocks.map((x) => x.completionMillisecondsPerFrame),
        frames: 90,
      };
    }),
  );
  const files = [
    'web/shader.js',
    'research/webgl.mjs',
    ...variantFiles,
    dir + 'final/browser-gpu.mjs',
    dir + 'final/benchmark-webgl.mjs',
    dir + 'results/benchmark.json',
  ];
  const hashes = Object.fromEntries(
    await Promise.all(
      files.map(async (p) => [
        p,
        createHash('sha256')
          .update(await readFile(p))
          .digest('hex'),
      ]),
    ),
  );
  await writeFile(
    dir + 'final/results/webgl-benchmark.json',
    JSON.stringify(
      {
        date: new Date().toISOString(),
        hardware: gpu.hardware,
        hashes,
        shaderHashes,
        method:
          'WebGL2 RGBA8 offscreen 1280x720, same four native scenes/uniforms, 24 interactions. Three alternating-order blocks per scene/variant; five warmup and thirty measured draws. One EXT_disjoint_timer_query_webgl2 query covers each thirty-draw block; elapsed time divided by thirty; disjoint blocks rejected. Also reports wall time for thirty draws plus one 1-pixel synchronous readback, divided by thirty (amortized submission/completion, not display FPS). Compilation, warmup, full-image readback, Playwright IPC, UI and vsync excluded.',
        measurements,
        summaries,
      },
      null,
      2,
    ) + '\n',
  );
} finally {
  await gpu.close();
}
